package com.tencent.weknora.storage;
import com.fasterxml.jackson.databind.*;
import java.nio.file.*;
import java.util.*;
import org.junit.jupiter.api.*;
import org.junit.jupiter.api.io.TempDir;
import static org.assertj.core.api.Assertions.*;

/** Actual Go resource wrapper registration outputs with its Unix MIME tables captured alongside the oracle. */
class StorageMimeCompatibilityTest {
    @TempDir Path temp;
    static JsonNode oracle()throws Exception{try(var input=StorageMimeCompatibilityTest.class.getResourceAsStream("/go-storage-mime.json")){return new ObjectMapper().readTree(input);}}
    @Test void realGoRegistrationMetadataMatchesAllCapturedSystemExtensionsAndFilenameEdges()throws Exception{JsonNode data=oracle();List<Path> globs=new ArrayList<>(),types=new ArrayList<>();for(var file:data.path("system_files")){Path path=temp.resolve(Integer.toString(globs.size()+types.size()));Files.writeString(path,file.path("content").asText());(file.path("path").asText().endsWith("globs2")?globs:types).add(path);}var mime=new GoMimeTypes(globs,types);for(var row:data.path("rows")){String name=row.path("name").asText();var meta=mime.metadata(name);assertThat(meta.mime()).as("MIME %s",name).isEqualTo(row.path("mime").asText());assertThat(meta.kind()).as("kind %s",name).isEqualTo(row.path("kind").asText());assertThat(meta.name()).as("basename %s",name).isEqualTo(row.path("original_name").asText());}}
    @Test void actualGoMimeParametersMatchCharsetNormalizationValidationAndContinuation()throws Exception{for(var row:oracle().path("parameters")){String actual=GoMimeMediaType.normalize(row.path("input").asText());if(row.path("valid").asBoolean())assertThat(actual).as("media type %s",row).isEqualTo(row.path("output").asText());else assertThat(actual).as("invalid %s",row).isNull();}}
    @Test void globsTakeFirstExistingFileAndFirstExactExtensionWhileKeepingBuiltinMappings()throws Exception{Path first=temp.resolve("globs"),second=temp.resolve("second"),type=temp.resolve("types");Files.writeString(first,"#comment\n50:text/x-first:*.unit\n60:application/second:*.unit\n50:application/ignored:*.png\n50:application/upper:*.UNIT\n50:application/glob:*.glob?\n50:bad type:*.invalid\n50:application/deep:*.two.ext:cs\n");Files.writeString(second,"50:application/second:*.later\n");Files.writeString(type,"application/types later\n");var mime=new GoMimeTypes(List.of(temp.resolve("missing"),first,second),List.of(type));assertThat(mime.extension(".unit")).isEqualTo("text/x-first; charset=utf-8");assertThat(mime.extension(".UNIT")).isEqualTo("application/upper");assertThat(mime.extension(".UnIt")).isEqualTo("application/upper");assertThat(mime.extension(".png")).isEqualTo("image/png");assertThat(mime.extension(".later")).isEmpty();assertThat(mime.extension(".invalid")).isEmpty();assertThat(mime.extension(".glob?")).isEmpty();assertThat(mime.extension(".two.ext")).isEqualTo("application/deep");}
    @Test void mimeTypesFallbackLoadsEveryFileAndLastEntryOverwritesEarlierMappings()throws Exception{Path one=temp.resolve("one"),two=temp.resolve("two");Files.writeString(one,"#comment\ntext/x-first unit unit2 #ignore ignored\napplication/first TXT\napplication/x-new\u00a0unicode\n");Files.writeString(two,"application/second unit\ntext/plain txt\n");var mime=new GoMimeTypes(List.of(temp.resolve("missing")),List.of(one,two));assertThat(mime.extension(".unit")).isEqualTo("application/second");assertThat(mime.extension(".unit2")).isEqualTo("text/x-first; charset=utf-8");assertThat(mime.extension(".TXT")).isEqualTo("application/first");assertThat(mime.extension(".txt")).isEqualTo("text/plain; charset=utf-8");assertThat(mime.extension(".TxT")).isEqualTo("text/plain; charset=utf-8");assertThat(mime.extension(".ignored")).isEmpty();assertThat(mime.extension(".unicode")).isEqualTo("application/x-new");}
}
